<?php require '../config.php';require_admin();$rows=$pdo->query("SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><title>Products</title><link rel="stylesheet" href="../assets/style.css"></head><body><main><h1>Manage Products</h1><a href="index.php">Dashboard</a> · <a href="product_add.php">Add product</a><table><tr><th>Image</th><th>Name</th><th>Category</th><th>Price</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?php if($r['picture']):?><img class="thumb" src="../<?=h($r['picture'])?>" alt="product"><?php endif;?></td><td><?=h($r['pname'])?></td><td><?=h($r['category'])?></td><td><?=number_format($r['price'],2)?></td><td><a href="product_edit.php?id=<?=$r['id']?>">Edit</a> · <a href="product_delete.php?id=<?=$r['id']?>" onclick="return confirm('Delete product?')">Delete</a></td></tr><?php endforeach;?></table></main></body></html>